input.sparql:
SELECT ?entity ?point ?ts WHERE {
  VALUES ?name { "Chiller02" "CondPump01" "CondPump02" }
  ?entity rdfs:label ?name .
  ?point brick:isPointOf ?entity .
  ?point rdf:type ?type .
  # Look for power or energy sensors
  FILTER(?type IN (brick:Electric_Power_Sensor, brick:Energy_Sensor))
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

SELECT ?entity ?name ?point ?pointType ?ts WHERE {
  VALUES ?name { "Chiller02" "CondPump01" "CondPump02" }
  ?entity rdfs:label ?name .
  ?point brick:isPointOf ?entity .
  ?point rdf:type ?pointType .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

SELECT ?entity ?label WHERE {
  ?entity rdfs:label ?label .
  FILTER(CONTAINS(?label, "Chiller02") || CONTAINS(?label, "CondPump01") || CONTAINS(?label, "CondPump02"))
}
